namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public static class RecipeStore
{
    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe
        {
            Id = 1,
            Title = "Classic Margherita Pizza",
            Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 2,
            Title = "Chicken Tikka Masala",
            Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 minutes.\n5. Add cream and cooked chicken.\n6. Simmer 10 more minutes. Serve with rice.",
            Ratings = new List<int> { 5, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 3,
            Title = "Beef Tacos",
            Category = "Mexican",
            Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nTaco seasoning\nOnion",
            Steps = "1. Brown ground beef with diced onion.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm taco shells in oven.\n4. Fill shells with beef mixture.\n5. Top with lettuce, tomato, cheese, and sour cream.",
            Ratings = new List<int> { 4, 4, 3 }
        },
        new Recipe
        {
            Id = 4,
            Title = "Chocolate Lava Cake",
            Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs.\n5. Add flour and vanilla, mix gently.\n6. Pour into greased ramekins.\n7. Bake 12-14 minutes until edges are set but center is soft.",
            Ratings = new List<int> { 5, 5, 5, 4 }
        },
        new Recipe
        {
            Id = 5,
            Title = "Pad Thai",
            Category = "Asian",
            Ingredients = "Rice noodles\nShrimp or tofu\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
            Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Make sauce: mix tamarind paste, fish sauce, and sugar.\n3. Stir-fry shrimp or tofu until cooked.\n4. Push aside, scramble eggs in the pan.\n5. Add drained noodles and sauce, toss together.\n6. Top with bean sprouts, peanuts, green onions, and lime.",
            Ratings = new List<int> { 4, 5, 4 }
        },
        new Recipe
        {
            Id = 6,
            Title = "Caesar Salad",
            Category = "Salads",
            Ingredients = "Romaine lettuce\nParmesan cheese\nCroutons\nCaesar dressing\nLemon juice\nGarlic\nAnchovy paste\nOlive oil",
            Steps = "1. Wash and chop romaine lettuce.\n2. Make dressing: whisk garlic, anchovy paste, lemon juice, and olive oil.\n3. Toss lettuce with dressing.\n4. Top with shaved Parmesan and croutons.\n5. Serve immediately.",
            Ratings = new List<int> { 4, 3, 4 }
        }
    };

    public static List<string> Categories =>
        Recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
}

@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>@Category Recipes - Recipe Community</PageTitle>

<h1>@Category Recipes</h1>

<div class="row">
    @foreach (var recipe in GetRecipes())
    {
        <div class="col-md-6 col-lg-4 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">
                        @if (recipe.Ratings.Count > 0)
                        {
                            <span>@GetStars(recipe.AverageRating) (@recipe.Ratings.Count ratings)</span>
                        }
                        else
                        {
                            <span>No ratings yet</span>
                        }
                    </p>
                    <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<Recipe> GetRecipes() =>
        RecipeStore.Recipes.Where(r => r.Category == Category).ToList();

    private string GetStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@recipe?.Title - Recipe Community</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                        {
                            <li>• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Instructions</h5></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <h4>Rate this Recipe</h4>
        <StarRating RecipeId="@recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <a href="/recipes/@recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @recipe.Category Recipes</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}

@using RecipeCommunity.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              style="cursor: pointer; font-size: 2rem; color: @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "#ffc107" : "#dee2e6");">
            ★
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
    @if (recipe is not null && recipe.Ratings.Count > 0)
    {
        <div class="text-muted mt-1">
            Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.Ratings.Count ratings)
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Recipe? recipe;
    private int currentRating;
    private int hoverRating;
    private bool submitted;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == RecipeId);
    }

    private void Rate(int stars)
    {
        currentRating = stars;
        if (recipe is not null)
        {
            recipe.Ratings.Add(stars);
            submitted = true;
        }
    }
}

@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (isSubmitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added to the @category category.</p>
        <a href="/recipes/@category" class="btn btn-primary">View in @category</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="@this" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label">Recipe Title</label>
                    <InputText @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                    @if (showValidation && string.IsNullOrWhiteSpace(title))
                    {
                        <div class="text-danger">Title is required.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Category</label>
                    <InputSelect @bind-Value="category" class="form-select">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeStore.Categories)
                        {
                            <option value="@cat">@cat</option>
                        }
                        <option value="Other">Other</option>
                    </InputSelect>
                    @if (showValidation && string.IsNullOrWhiteSpace(category))
                    {
                        <div class="text-danger">Category is required.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Ingredients</label>
                    <InputTextArea @bind-Value="ingredients" class="form-control" rows="6"
                        placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                    @if (showValidation && string.IsNullOrWhiteSpace(ingredients))
                    {
                        <div class="text-danger">Ingredients are required.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Steps</label>
                    <InputTextArea @bind-Value="steps" class="form-control" rows="8"
                        placeholder="Describe each step&#10;e.g.,&#10;1. Preheat oven to 350°F.&#10;2. Mix dry ingredients together.&#10;3. Add wet ingredients and stir." />
                    @if (showValidation && string.IsNullOrWhiteSpace(steps))
                    {
                        <div class="text-danger">Steps are required.</div>
                    }
                </div>

                <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
            </div>
        </div>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool isSubmitted;
    private bool showValidation;

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) ||
            string.IsNullOrWhiteSpace(category) ||
            string.IsNullOrWhiteSpace(ingredients) ||
            string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        var newRecipe = new Recipe
        {
            Id = RecipeStore.Recipes.Max(r => r.Id) + 1,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };

        RecipeStore.Recipes.Add(newRecipe);
        isSubmitted = true;
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        isSubmitted = false;
        showValidation = false;
    }
}

