{"path": "/tmp/sv-db48628cba404e84ac88c47e304751a5/RecipeCommunity/Components/Pages/StarRating.razor", "file_text": "@using RecipeCommunity.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              style="cursor: pointer; font-size: 2rem; color: @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "#ffc107" : "#dee2e6");">
            ★
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
    @if (recipe is not null && recipe.Ratings.Count > 0)
    {
        <div class="text-muted mt-1">
            Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.Ratings.Count ratings)
        </div>
    }
</div>

