@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>@Category Recipes - Recipe Community</PageTitle>

<h1>@Category Recipes</h1>

<div class="row">
    @foreach (var recipe in GetRecipes())
    {
        <div class="col-md-6 col-lg-4 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@recipe.Title</h5>
                    <p class="card-text text-muted">
                        @if (recipe.Ratings.Count > 0)
                        {
                            <span>@GetStars(recipe.AverageRating) (@recipe.Ratings.Count ratings)</span>
                        }
                        else
                        {
                            <span>No ratings yet</span>
                        }
                    </p>
                    <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                </div>
            </div>
        </div>
    }
</div>

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private List<Recipe> GetRecipes() =>
        RecipeStore.Recipes.Where(r => r.Category == Category).ToList();

    private string GetStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models

<PageTitle>@recipe?.Title - Recipe Community</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <div class="card-body">
                    <ul class="list-unstyled mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                        {
                            <li>• @ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Instructions</h5></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <h4>Rate this Recipe</h4>
        <StarRating RecipeId="@recipe.Id" @rendermode="InteractiveServer" />
    </div>

    <a href="/recipes/@recipe.Category" class="btn btn-outline-secondary mt-3">← Back to @recipe.Category Recipes</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == Id);
    }
}

@using RecipeCommunity.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              style="cursor: pointer; font-size: 2rem; color: @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "#ffc107" : "#dee2e6");">
            ★
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
    @if (recipe is not null && recipe.Ratings.Count > 0)
    {
        <div class="text-muted mt-1">
            Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.Ratings.Count ratings)
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private Recipe? recipe;
    private int currentRating;
    private int hoverRating;
    private bool submitted;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.Recipes.FirstOrDefault(r => r.Id == RecipeId);
    }

    private void Rate(int stars)
    {
        currentRating = stars;
        if (recipe is not null)
        {
            recipe.Ratings.Add(stars);
            submitted = true;
        }
    }
}

