@page "/submit"
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (isSubmitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added to the @category category.</p>
        <a href="/recipes/@category" class="btn btn-primary">View in @category</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="@this" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label">Recipe Title</label>
                    <InputText @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                    @if (showValidation && string.IsNullOrWhiteSpace(title))
                    {
                        <div class="text-danger">Title is required.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Category</label>
                    <InputSelect @bind-Value="category" class="form-select">
                        <option value="">-- Select a category --</option>
                        @foreach (var cat in RecipeStore.Categories)
                        {
                            <option value="@cat">@cat</option>
                        }
                        <option value="Other">Other</option>
                    </InputSelect>
                    @if (showValidation && string.IsNullOrWhiteSpace(category))
                    {
                        <div class="text-danger">Category is required.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Ingredients</label>
                    <InputTextArea @bind-Value="ingredients" class="form-control" rows="6"
                        placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                    @if (showValidation && string.IsNullOrWhiteSpace(ingredients))
                    {
                        <div class="text-danger">Ingredients are required.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Steps</label>
                    <InputTextArea @bind-Value="steps" class="form-control" rows="8"
                        placeholder="Describe each step&#10;e.g.,&#10;1. Preheat oven to 350°F.&#10;2. Mix dry ingredients together.&#10;3. Add wet ingredients and stir." />
                    @if (showValidation && string.IsNullOrWhiteSpace(steps))
                    {
                        <div class="text-danger">Steps are required.</div>
                    }
                </div>

                <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
            </div>
        </div>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool isSubmitted;
    private bool showValidation;

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) ||
            string.IsNullOrWhiteSpace(category) ||
            string.IsNullOrWhiteSpace(ingredients) ||
            string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        var newRecipe = new Recipe
        {
            Id = RecipeStore.Recipes.Max(r => r.Id) + 1,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };

        RecipeStore.Recipes.Add(newRecipe);
        isSubmitted = true;
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        ingredients = string.Empty;
        steps = string.Empty;
        isSubmitted = false;
        showValidation = false;
    }
}

