@page "/"
@using RecipeCommunity.Models

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeStore.Categories)
    {
        <div class="col-md-4 col-lg-3 mb-3">
            <a href="/recipes/@category" class="text-decoration-none">
                <div class="card h-100 text-center border-primary">
                    <div class="card-body">
                        <h4 class="card-title">@GetEmoji(category) @category</h4>
                        <p class="card-text text-muted">
                            @RecipeStore.Recipes.Count(r => r.Category == category) recipes
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-4">
    <a href="/submit" class="btn btn-success btn-lg">📝 Submit Your Recipe</a>
</div>

@code {
    private string GetEmoji(string category) => category switch
    {
        "Italian" => "🍕",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        "Asian" => "🥢",
        "Salads" => "🥗",
        _ => "🍽️"
    };
}

